<?php
require __DIR__.'/lib.php';
$id=(string)($_GET['id']??'');$article=null;foreach(db_read('content') as $row)if(($row['id']??'')===$id && ($row['type']??'')==='berita'){$article=$row;break;}
if(!$article){http_response_code(404);exit('Berita yang diminta tidak ditemukan.');}
$images=array_values(array_filter($article['images']??[],'is_string'));if(!$images&&!empty($article['image']))$images=[$article['image']];$images=array_slice($images,0,5);
$cfg=require __DIR__.'/ahli-waris/config.php';$db=null;$comments=[];$message='';
try{
 $db=new PDO('mysql:host='.$cfg['host'].';port='.($cfg['port']??3306).';dbname='.$cfg['database'].';charset=utf8mb4',$cfg['username'],$cfg['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
 $db->exec('CREATE TABLE IF NOT EXISTS mobile_news_comments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,news_id VARCHAR(80) NOT NULL,user_id VARCHAR(80) NOT NULL,display_name VARCHAR(160) NOT NULL,parent_id BIGINT UNSIGNED NULL,body TEXT NOT NULL,hidden TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_news(news_id,id),INDEX idx_user(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4');
}catch(Throwable $e){error_log('Berita gallery comments: '.$e->getMessage());$db=null;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf_check();
 if(!$db)$message='Layanan komentar sementara tidak tersedia.';
 elseif(($_POST['action']??'')==='hide'&&is_admin()){
  $st=$db->prepare('UPDATE mobile_news_comments SET hidden=1 WHERE id=? AND news_id=?');$st->execute([(int)($_POST['comment_id']??0),$id]);$message='Komentar disembunyikan oleh moderator.';
 }elseif(($_POST['action']??'')==='comment'){
  $uid=(string)($_SESSION['portal_uid']??'');$name=(string)($_SESSION['portal_name']??'');if(is_admin()){$uid='admin';$name='Administrator';}
  if($uid==='')$message='Silakan masuk ke akun Cikoko untuk memberikan komentar.';
  else{
   $body=trim((string)($_POST['message']??''));$parent=(int)($_POST['parent']??0);
   if(strlen($body)<2||strlen($body)>1200||preg_match('/\b(anjing|bangsat|kontol|memek|tolol|goblok|bajingan)\b/ui',$body))$message='Komentar belum dapat diterima. Mohon gunakan bahasa yang santun.';
   else{
    if($parent){$check=$db->prepare('SELECT id FROM mobile_news_comments WHERE id=? AND news_id=? AND hidden=0');$check->execute([$parent,$id]);if(!$check->fetchColumn())$parent=0;}
    $st=$db->prepare('INSERT INTO mobile_news_comments(news_id,user_id,display_name,parent_id,body) VALUES(?,?,?,?,?)');$st->execute([$id,$uid,$name?:'Pengguna Cikoko',$parent?:null,$body]);
    header('Location: berita-galeri.php?id='.urlencode($id).'#komentar',true,303);exit;
   }
  }
 }
}
if($db){$st=$db->prepare('SELECT id,display_name,parent_id,body,created_at FROM mobile_news_comments WHERE news_id=? AND hidden=0 ORDER BY id ASC LIMIT 100');$st->execute([$id]);$comments=$st->fetchAll();}
$link='https://datawebs.my.id/berita-galeri.php?id='.rawurlencode($id);
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=esc($article['title']??'Berita')?> — Cikoko</title><style>
*{box-sizing:border-box}body{margin:0;background:#f2f6fb;color:#173957;font:14px system-ui,sans-serif}header{background:#10375f;color:white;padding:19px 22px;display:flex;justify-content:space-between}header a{color:white}main{max-width:860px;margin:25px auto;padding:0 15px}.card{background:#fff;padding:18px;border:1px solid #e0eaf3;border-radius:16px;margin-bottom:14px}h1{font-size:25px;margin:12px 0}.gallery{position:relative}.gallery img{width:100%;max-height:480px;object-fit:contain;background:#dfeaf5;border-radius:12px;display:none}.gallery img.active{display:block}.controls{display:flex;justify-content:space-between;margin:8px 0}.controls button,.submit{background:#216bdb;color:#fff;border:0;border-radius:9px;padding:10px 16px;cursor:pointer}.share{display:flex;gap:10px;margin:18px 0}.share a,.share button{height:42px;width:42px;border-radius:50%;display:grid;place-items:center;background:#e8f0fc;border:0;text-decoration:none;color:#124a96;font-size:20px;cursor:pointer}.share .wa{background:#dcf9e4;color:#15944a}.share .fb{background:#e4eeff;color:#1f58aa}.text{white-space:pre-wrap;line-height:1.7;color:#334e66}.comment{border-top:1px solid #e0e8f0;padding:12px 0}.comment small{color:#7d8fa0}.comment.reply{margin-left:22px}textarea{display:block;width:100%;padding:11px;border:1px solid #cad8e8;border-radius:9px;font:inherit}.notice{background:#fff5dc;padding:12px;border-radius:8px}a{color:#1a5eb9}
</style></head><body><header><b>Kelurahan Cikoko · Berita</b><a href="index.php">Beranda</a></header><main><article class="card"><div class="gallery" id="galeri"><?php foreach($images as $i=>$path):?><img class="<?=$i===0?'active':''?>" src="<?=esc(url($path))?>" alt="Foto berita ke-<?=$i+1?>"><?php endforeach;?></div><?php if(count($images)>1):?><div class="controls"><button onclick="geser(-1)" aria-label="Foto sebelumnya">‹ Sebelumnya</button><span id="jumlah">1 / <?=count($images)?></span><button onclick="geser(1)" aria-label="Foto berikutnya">Berikutnya ›</button></div><?php endif;?><h1><?=esc($article['title']??'Berita Kelurahan')?></h1><p class="text"><?=esc($article['body']??'')?></p><div class="share"><a class="wa" aria-label="Bagikan ke WhatsApp" href="https://wa.me/?text=<?=rawurlencode($link)?>" target="_blank" rel="noopener">◉</a><a class="fb" aria-label="Bagikan ke Facebook" href="https://www.facebook.com/sharer/sharer.php?u=<?=rawurlencode($link)?>" target="_blank" rel="noopener">f</a><button aria-label="Salin tautan untuk Instagram" onclick="salin()">◎</button><button aria-label="Salin tautan" onclick="salin()">↗</button></div></article><section class="card" id="komentar"><h2>Komentar dan Tanggapan</h2><?php if($message):?><div class="notice"><?=esc($message)?></div><?php endif;?><?php foreach($comments as $c):?><div class="comment <?=$c['parent_id']?'reply':''?>"><b><?=esc($c['display_name'])?></b> <small><?=esc($c['created_at'])?></small><p class="text"><?=esc($c['body'])?></p><a href="#komentar" onclick="balas(<?=intval($c['id'])?>)">Balas</a><?php if(is_admin()):?><form method="post" style="display:inline;margin-left:12px"><input type="hidden" name="csrf" value="<?=esc(csrf())?>"><input type="hidden" name="action" value="hide"><input type="hidden" name="comment_id" value="<?=intval($c['id'])?>"><button class="submit" style="padding:4px 8px">Sembunyikan</button></form><?php endif;?></div><?php endforeach;?><?php if(!$comments):?><p>Belum ada komentar.</p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=esc(csrf())?>"><input type="hidden" name="action" value="comment"><input type="hidden" id="parent" name="parent" value="0"><small id="reply-label"></small><textarea maxlength="1200" name="message" required rows="3" placeholder="Tulis komentar dengan bahasa yang santun…"></textarea><button class="submit" style="margin-top:10px">Kirim Komentar</button></form></section></main><script>let position=0;function geser(step){const imgs=[...document.querySelectorAll('#galeri img')];if(!imgs.length)return;imgs[position].classList.remove('active');position=(position+step+imgs.length)%imgs.length;imgs[position].classList.add('active');document.getElementById('jumlah').textContent=(position+1)+' / '+imgs.length;}function balas(id){document.getElementById('parent').value=id;document.getElementById('reply-label').textContent='Membalas komentar #'+id;}function salin(){navigator.clipboard.writeText(<?=json_encode($link,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP)?>).then(()=>alert('Tautan berita disalin.'));}</script></body></html>
